package pe.edu.upeu.casaonada.visita.api;
import pe.edu.upeu.casaonada.visita.domain.EstadoVisita; import pe.edu.upeu.casaonada.visita.dto.*; import pe.edu.upeu.casaonada.visita.service.VisitaService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @RequestMapping("/api/v1/visitas") public class VisitaController { private final VisitaService s; public VisitaController(VisitaService s){this.s=s;} @PostMapping public ResponseEntity<VisitaResponse> crear(@Valid @RequestBody VisitaRequest r){var x=s.crear(r);return ResponseEntity.created(URI.create("/api/v1/visitas/"+x.id())).body(x);} @GetMapping public List<VisitaResponse> listar(){return s.listar();} @GetMapping("/{id}") public VisitaResponse buscar(@PathVariable Long id){return s.buscar(id);} @PutMapping("/{id}") public VisitaResponse actualizar(@PathVariable Long id,@Valid @RequestBody VisitaRequest r){return s.actualizar(id,r);} @PatchMapping("/{id}/estado") public VisitaResponse estado(@PathVariable Long id,@RequestBody Map<String,String> b){return s.cambiarEstado(id,EstadoVisita.valueOf(b.get("estado")));} }
